/**
 * Array utility helpers — typed, functional, single-responsibility.
 */

/** Returns the first element of an array, or undefined for empty arrays. */
export function first<T>(items: T[]): T | undefined {
  return items[0];
}

/** Returns the last element of an array, or undefined for empty arrays. */
export function last<T>(items: T[]): T | undefined {
  return items[items.length - 1];
}

/** Removes duplicate values from an array while preserving insertion order. */
export function unique<T>(items: T[]): T[] {
  return [...new Set(items)];
}

/** Splits an array into chunks of the given size. */
export function chunk<T>(items: T[], size: number): T[][] {
  if (size <= 0) return [];
  const result: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

/** Returns the sum of all numbers in the array. */
export function sum(values: number[]): number {
  return values.reduce((acc, v) => acc + v, 0);
}

/** Returns the arithmetic mean of the array, or 0 for empty arrays. */
export function mean(values: number[]): number {
  if (values.length === 0) return 0;
  return sum(values) / values.length;
}

/**
 * Date utility helpers — thin wrappers over the Date built-in.
 */

/** Returns true when the given Date falls on a weekend (Saturday or Sunday). */
export function isWeekend(date: Date): boolean {
  const day = date.getDay();
  return day === 0 || day === 6;
}

/** Returns the number of full days between two dates (end − start). */
export function daysBetween(start: Date, end: Date): number {
  const msPerDay = 1000 * 60 * 60 * 24;
  return Math.floor((end.getTime() - start.getTime()) / msPerDay);
}

/** Returns a new Date that is `days` after the given date. */
export function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

/** Formats a Date as an ISO-8601 date string (YYYY-MM-DD). */
export function formatDate(date: Date): string {
  return date.toISOString().slice(0, 10);
}

/** Returns true when the year of a given Date is a leap year. */
export function isLeapYear(date: Date): boolean {
  const year = date.getFullYear();
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

