"""List helper utilities — clean, functional, with type hints."""
from typing import List, TypeVar, Optional

T = TypeVar("T")


def first(items: List[T]) -> Optional[T]:
    """Return the first element of a list, or None for empty lists."""
    return items[0] if items else None


def last(items: List[T]) -> Optional[T]:
    """Return the last element of a list, or None for empty lists."""
    return items[-1] if items else None


def flatten(nested: List[List[T]]) -> List[T]:
    """Flatten a list of lists into a single list."""
    result: List[T] = []
    for sublist in nested:
        result.extend(sublist)
    return result


def deduplicate(items: List[T]) -> List[T]:
    """Return a new list with duplicate values removed, preserving order."""
    seen: set = set()
    result: List[T] = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result


def chunk(items: List[T], size: int) -> List[List[T]]:
    """Split items into chunks of the given size."""
    if size <= 0:
        return []
    return [items[i : i + size] for i in range(0, len(items), size)]

/**
 * Mathematical helpers — pure functions, no side effects.
 */

/** Clamps value to the inclusive range [min, max]. */
export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/** Returns base raised to the power of exponent using iterative multiplication. */
export function power(base: number, exponent: number): number {
  if (exponent === 0) return 1;
  let result = 1;
  const abs = Math.abs(exponent);
  for (let i = 0; i < abs; i++) {
    result *= base;
  }
  return exponent < 0 ? 1 / result : result;
}

/** Returns true when n is a prime number. */
export function isPrime(n: number): boolean {
  if (n < 2) return false;
  if (n === 2) return true;
  if (n % 2 === 0) return false;
  for (let i = 3; i <= Math.sqrt(n); i += 2) {
    if (n % i === 0) return false;
  }
  return true;
}

/** Computes the greatest common divisor of two non-negative integers. */
export function gcd(a: number, b: number): number {
  while (b !== 0) {
    const temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}

/** Rounds n to the given number of decimal places. */
export function roundTo(n: number, decimals: number): number {
  const factor = Math.pow(10, decimals);
  return Math.round(n * factor) / factor;
}

