// Contains reports whether target is present in items.
func Contains(items []int, target int) bool {
	for _, v := range items {
		if v == target {
			return true
		}
	}
	return false
}

// Sum returns the sum of all integers in items.
func Sum(items []int) int {
	total := 0
	for _, v := range items {
		total += v
	}
	return total
}

// Filter returns a new slice containing only elements for which predicate is true.
func Filter(items []int, predicate func(int) bool) []int {
	result := make([]int, 0)
	for _, v := range items {
		if predicate(v) {
			result = append(result, v)
		}
	}
	return result
}

// Map applies transform to each element and returns the resulting slice.
func Map(items []int, transform func(int) int) []int {
	result := make([]int, len(items))
	for i, v := range items {
		result[i] = transform(v)
	}
	return result
}

// Unique returns a new slice with duplicate values removed (preserving order).
func Unique(items []int) []int {
	seen := make(map[int]bool)
	result := make([]int, 0)
	for _, v := range items {
		if !seen[v] {
			seen[v] = true
			result = append(result, v)
		}
	}
	return result
}

/**
 * String utility helpers — clean, well-typed functions.
 */

/** Capitalises the first character of each word. */
export function titleCase(text: string): string {
  return text
    .split(' ')
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join(' ');
}

/** Truncates text to maxLength, appending suffix if needed. */
export function truncate(text: string, maxLength: number, suffix = '...'): string {
  if (text.length <= maxLength) return text;
  return text.slice(0, maxLength - suffix.length) + suffix;
}

/** Returns true when the string is null, undefined, or contains only whitespace. */
export function isBlank(text: string | null | undefined): boolean {
  return text == null || text.trim() === '';
}

/** Converts camelCase to kebab-case (e.g. 'myComponent' → 'my-component'). */
export function toKebabCase(text: string): string {
  return text.replace(/([a-z])([A-Z])/g, '$1-$2').toLowerCase();
}

/** Counts occurrences of a substring within a string. */
export function countOccurrences(text: string, search: string): number {
  if (search.length === 0) return 0;
  let count = 0;
  let pos = text.indexOf(search);
  while (pos !== -1) {
    count++;
    pos = text.indexOf(search, pos + search.length);
  }
  return count;
}

