package unusedwrite

import (
	_ "embed"
	"go/types"

	"golang.org/x/tools/go/analysis"
	"golang.org/x/tools/go/analysis/passes/buildssa"
	"golang.org/x/tools/go/ssa"
	"golang.org/x/tools/internal/analysis/analyzerutil"
	"golang.org/x/tools/internal/typeparams"
)

//go:embed doc.go
var doc string

// Analyzer reports instances of writes to struct fields and arrays
// that are never read.
var Analyzer = &analysis.Analyzer{
	Name:     "unusedwrite",
	Doc:      analyzerutil.MustExtractDoc(doc, "unusedwrite"),
	URL:      "https://pkg.go.dev/golang.org/x/tools/go/analysis/passes/unusedwrite",
	Requires: []*analysis.Analyzer{buildssa.Analyzer},
	Run:      run,
}

func run(pass *analysis.Pass) (any, error) {
	for _, pkg := range pass.Pkg.Imports() {
		if pkg.Path() == "unsafe" {
			// See golang/go#67684, or testdata/src/importsunsafe: the unusedwrite
			// analyzer may have false positives when used with unsafe.
			return nil, nil
		}
	}

	ssainput := pass.ResultOf[buildssa.Analyzer].(*buildssa.SSA)
	for _, fn := range ssainput.SrcFuncs {
		reports := checkStores(fn)
		for _, store := range reports {
			switch addr := store.Addr.(type) {
			case *ssa.FieldAddr:
				field := typeparams.CoreType(typeparams.MustDeref(addr.X.Type())).(*types.Struct).Field(addr.Field)
				pass.Reportf(store.Pos(),
					"unused write to field %s", field.Name())
			case *ssa.IndexAddr:
				pass.Reportf(store.Pos(),
					"unused write to array index %s", addr.Index)
			}
		}
	}
	return nil, nil
}

// checkStores returns *Stores in fn whose address is written to but never used.
func checkStores(fn *ssa.Function) []*ssa.Store {
	var reports []*ssa.Store
	// Visit each block. No need to visit fn.Recover.
	for _, blk := range fn.Blocks {
		for _, instr := range blk.Instrs {
			// Identify writes.
			if store, ok := instr.(*ssa.Store); ok {
				// Consider field/index writes to an object whose elements are copied and not shared.
				// MapUpdate is excluded since only the reference of the map is copied.
				switch addr := store.Addr.(type) {
				case *ssa.FieldAddr:
					if isDeadStore(store, addr.X, addr) {
						reports = append(reports, store)
					}
				case *ssa.IndexAddr:
					if isDeadStore(store, addr.X, addr) {
						reports = append(reports, store)
					}
				}
			}
		}
	}
	return reports
}

// isDeadStore determines whether a field/index write to an object is dead.
// Argument "obj" is the object, and "addr" is the instruction fetching the field/index.
func isDeadStore(store *ssa.Store, obj ssa.Value, addr ssa.Instruction) bool {
	// Consider only struct or array objects.
	if !hasStructOrArrayType(obj) {
		return false
	}
	// Check liveness: if the value is used later, then don't report the write.
	for _, ref := range *obj.Referrers() {
		if ref == store || ref == addr {
			continue
		}
		switch ins := ref.(type) {
		case ssa.CallInstruction:
			return false
		case *ssa.FieldAddr:
			// Check whether the same field is used.
			if ins.X == obj {
				if faddr, ok := addr.(*ssa.FieldAddr); ok {
					if faddr.Field == ins.Field {
						return false
					}
				}
			}
			// Otherwise another field is used, and this usage doesn't count.
			continue
		case *ssa.IndexAddr:
			if ins.X == obj {
				return false
			}
			continue // Otherwise another object is used
		case *ssa.Lookup:
			if ins.X == obj {
				return false
			}
			continue // Otherwise another object is used
		case *ssa.Store:
			if ins.Val == obj {
				return false
			}
			continue // Otherwise other object is stored
		default: // consider live if the object is used in any other instruction
			return false
		}
	}
	return true
}

// isStructOrArray returns whether the underlying type is struct or array.
func isStructOrArray(tp types.Type) bool {
	switch tp.Underlying().(type) {
	case *types.Array:
		return true
	case *types.Struct:
		return true
	}
	return false
}

// hasStructOrArrayType returns whether a value is of struct or array type.
func hasStructOrArrayType(v ssa.Value) bool {
	if instr, ok := v.(ssa.Instruction); ok {
		if alloc, ok := instr.(*ssa.Alloc); ok {
			// Check the element type of an allocated register (which always has pointer type)
			// e.g., for
			//   func (t T) f() { ...}
			// the receiver object is of type *T:
			//   t0 = local T (t)   *T
			if tp, ok := types.Unalias(alloc.Type()).(*types.Pointer); ok {
				return isStructOrArray(tp.Elem())
			}
			return false
		}
	}
	return isStructOrArray(v.Type())
}

"""Config loader with some nesting — borderline maintainability."""
from typing import Any, Dict, Optional


def resolve_config(
    base: Dict[str, Any],
    overrides: Optional[Dict[str, Any]] = None,
    env: str = "production",
) -> Dict[str, Any]:
    """Merge base config with optional overrides and environment-specific values."""
    result = dict(base)
    if overrides:
        for key, value in overrides.items():
            if key in result and isinstance(result[key], dict) and isinstance(value, dict):
                result[key] = resolve_config(result[key], value)
            else:
                result[key] = value
    if env == "development":
        result.setdefault("debug", True)
        result.setdefault("log_level", "DEBUG")
    elif env == "staging":
        result.setdefault("debug", False)
        result.setdefault("log_level", "INFO")
    elif env == "production":
        result.setdefault("debug", False)
        result.setdefault("log_level", "WARNING")
    return result


def get_nested(config: Dict[str, Any], *keys: str) -> Optional[Any]:
    """Navigate nested dict keys; return None if any key is missing."""
    current: Any = config
    for key in keys:
        if not isinstance(current, dict):
            return None
        current = current.get(key)
    return current

/**
 * Simple token parser — moderately complex, borderline health score.
 */

export type TokenType = 'number' | 'string' | 'boolean' | 'null' | 'identifier' | 'unknown';

export interface Token {
  type: TokenType;
  value: string;
  position: number;
}

/**
 * Tokenises a string expression into a list of typed tokens.
 * Handles numbers, quoted strings, booleans, null, and identifiers.
 */
export function tokenise(input: string): Token[] {
  const tokens: Token[] = [];
  let pos = 0;

  while (pos < input.length) {
    // Skip whitespace
    if (/\s/.test(input[pos])) {
      pos++;
      continue;
    }

    // Number
    if (/\d/.test(input[pos])) {
      let raw = '';
      while (pos < input.length && /[\d.]/.test(input[pos])) {
        raw += input[pos++];
      }
      tokens.push({ type: 'number', value: raw, position: pos - raw.length });
      continue;
    }

    // Quoted string
    if (input[pos] === '"') {
      let raw = '';
      pos++;
      while (pos < input.length && input[pos] !== '"') {
        raw += input[pos++];
      }
      pos++; // closing quote
      tokens.push({ type: 'string', value: raw, position: pos - raw.length - 2 });
      continue;
    }

    // Identifier / keyword
    if (/[a-zA-Z_]/.test(input[pos])) {
      let raw = '';
      while (pos < input.length && /\w/.test(input[pos])) {
        raw += input[pos++];
      }
      const type: TokenType =
        raw === 'true' || raw === 'false'
          ? 'boolean'
          : raw === 'null'
          ? 'null'
          : 'identifier';
      tokens.push({ type, value: raw, position: pos - raw.length });
      continue;
    }

    tokens.push({ type: 'unknown', value: input[pos], position: pos });
    pos++;
  }

  return tokens;
}

package router

import (
	"fmt"
	"strings"
)

// Route represents a URL pattern and its handler name.
type Route struct {
	Method  string
	Pattern string
	Handler string
}

// Router holds registered routes and dispatches requests.
type Router struct {
	routes []Route
}

// Register adds a new route to the router.
func (r *Router) Register(method, pattern, handler string) {
	r.routes = append(r.routes, Route{
		Method:  strings.ToUpper(method),
		Pattern: pattern,
		Handler: handler,
	})
}

// Dispatch finds a matching route and returns the handler name.
// Returns an empty string when no route matches.
func (r *Router) Dispatch(method, path string) string {
	method = strings.ToUpper(method)
	for _, route := range r.routes {
		if route.Method != method {
			continue
		}
		if route.Pattern == path {
			return route.Handler
		}
		if strings.HasSuffix(route.Pattern, "/*") {
			prefix := strings.TrimSuffix(route.Pattern, "/*")
			if strings.HasPrefix(path, prefix) {
				return route.Handler
			}
		}
	}
	return ""
}

// DebugRoutes returns a human-readable list of all registered routes.
func (r *Router) DebugRoutes() []string {
	result := make([]string, len(r.routes))
	for i, route := range r.routes {
		result[i] = fmt.Sprintf("[%s] %s -> %s", route.Method, route.Pattern, route.Handler)
	}
	return result
}

package fsm

import "fmt"

// State represents a named state in the finite state machine.
type State string

const (
	StateIdle       State = "idle"
	StateRunning    State = "running"
	StatePaused     State = "paused"
	StateStopped    State = "stopped"
)

// Event represents a transition trigger.
type Event string

const (
	EventStart  Event = "start"
	EventPause  Event = "pause"
	EventResume Event = "resume"
	EventStop   Event = "stop"
)

// Machine is a simple finite state machine.
type Machine struct {
	current State
}

// NewMachine returns a Machine in the idle state.
func NewMachine() *Machine {
	return &Machine{current: StateIdle}
}

// Current returns the active state.
func (m *Machine) Current() State {
	return m.current
}

// Transition applies an event and returns an error when the transition is invalid.
func (m *Machine) Transition(event Event) error {
	switch m.current {
	case StateIdle:
		if event == EventStart {
			m.current = StateRunning
			return nil
		}
	case StateRunning:
		if event == EventPause {
			m.current = StatePaused
			return nil
		}
		if event == EventStop {
			m.current = StateStopped
			return nil
		}
	case StatePaused:
		if event == EventResume {
			m.current = StateRunning
			return nil
		}
		if event == EventStop {
			m.current = StateStopped
			return nil
		}
	}
	return fmt.Errorf("invalid transition: %s -[%s]-> ?", m.current, event)
}

package main

import "fmt"

func processData(user User, config Config, logger Logger, db Database, cache Cache, options Options, reporter Reporter) error {
	if user.IsActive {
		for _, item := range db.GetItems() {
			switch item.Status {
			case "active":
				if item.Priority > 10 {
					for cache.IsLocked() {
						fmt.Println("waiting for cache")
					}
					if item.Type == "critical" {
						if config.Alerts {
							if reporter != nil {
								reporter.Alert(item.ID)
							}
						}
						logger.Log(fmt.Sprintf("critical item: %s", item.ID))
					} else {
						logger.Log(item.ID)
					}
				} else if item.Priority > 5 {
					if user.Role == "admin" {
						db.Prioritize(item.ID)
					}
				}
			case "pending":
				if item.CreatedAt < config.Cutoff {
					return fmt.Errorf("item %s is too old", item.ID)
				}
				if item.RetryCount > 3 {
					if config.AutoDelete {
						db.Delete(item.ID)
					} else {
						logger.Log(fmt.Sprintf("skipping expired: %s", item.ID))
					}
				}
			case "failed":
				logger.Log(fmt.Sprintf("failed item: %s", item.ID))
			}
		}
	}
	return nil
}

